/// <reference lib="webworker" />
import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { clientsClaim } from 'workbox-core';

declare let self: ServiceWorkerGlobalScope;

// Take control immediately on activation
self.skipWaiting();
clientsClaim();

// Clean up old cached versions
cleanupOutdatedCaches();

// Precache all assets generated by Vite build
precacheAndRoute(self.__WB_MANIFEST);

// Offline navigation fallback: return precached app shell (index.html) or offline.html
self.addEventListener('fetch', (event: FetchEvent) => {
  if (event.request.mode === 'navigate') {
    event.respondWith(
      fetch(event.request).catch(async () => {
        // 1. Try precached Single Page Application Shell
        const cachedAppShell = await caches.match('/index.html');
        if (cachedAppShell) return cachedAppShell;

        // 2. Try precached dedicated offline page
        const cachedOfflinePage = await caches.match('/offline.html');
        if (cachedOfflinePage) return cachedOfflinePage;

        // 3. Fallback inline HTML
        return new Response(
          '<!DOCTYPE html><html><head><title>Offline — PrepPilot</title></head><body style="background:#0f172a;color:#fff;font-family:sans-serif;padding:2rem;text-align:center;"><h2>Offline Mode</h2><p>PrepPilot study tools are saved locally on this device.</p></body></html>',
          { headers: { 'Content-Type': 'text/html' } }
        );
      })
    );
  }
});

// Background Web Push Notification Handler (FCM / Standard Web Push)
self.addEventListener('push', (event: PushEvent) => {
  if (!event.data) return;

  try {
    const payload = event.data.json();
    const notificationTitle =
      payload.notification?.title || payload.title || 'PrepPilot &bull; NIMCET 2027';

    const notificationOptions: NotificationOptions = {
      body:
        payload.notification?.body ||
        payload.body ||
        'You have an upcoming study milestone or revision scheduled.',
      icon: '/pwa-192x192.png',
      badge: '/pwa-192x192.png',
      data: payload.data || { url: '/' },
      tag: payload.tag || 'preppilot-study-reminder',
    };

    event.waitUntil(self.registration.showNotification(notificationTitle, notificationOptions));
  } catch (err) {
    console.warn('[sw.ts] Could not parse push payload:', err);
    // Plaintext fallback
    event.waitUntil(
      self.registration.showNotification('PrepPilot &bull; Study Reminder', {
        body: event.data.text() || 'Keep your NIMCET 2027 streak alive today.',
        icon: '/pwa-192x192.png',
      })
    );
  }
});

// Notification Click Handler: Focus existing tab or open target URL
self.addEventListener('notificationclick', (event: NotificationEvent) => {
  event.notification.close();
  const rawTarget = event.notification.data?.url || '/';
  const targetUrl = new URL(rawTarget, self.location.origin).href;

  event.waitUntil(
    self.clients
      .matchAll({ type: 'window', includeUncontrolled: true })
      .then((clientList) => {
        // If an app window is already open, focus it and optionally navigate
        for (const client of clientList) {
          if ('focus' in client) {
            if ('navigate' in client && client.url !== targetUrl && rawTarget !== '/') {
              client.navigate(targetUrl);
            }
            return client.focus();
          }
        }
        // Otherwise, open a new window
        if (self.clients.openWindow) {
          return self.clients.openWindow(targetUrl);
        }
      })
  );
});
